os:store.os:value:
#[output application/json --- {
  payload: write(payload, "application/json") replace /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/ with "<uuid>",
  mime: payload.^mimeType,
  rpc: attributes.jsonRpcMethod,
  taskIdIsUuid: (attributes.taskId default "") matches /[0-9a-f-]{36}/
}]

set-payload.value:
#[output application/json --- {
  status: vars.status,
  ctype: vars.ctype,
  body: vars.raw replace /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/ with "<uuid>" replace /20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9:.]+Z/ with "<ts>"
}]
